				return true;
			if ( CantDoAnything( from ) )
				return false;
			string title = null;
			if( move is NinjaMove )
				title = "Bushido";
			else if( move is SamuraiMove )
				title = "Ninjitsu";
			if ( title == null || name == null || m_Ruleset.GetOption( title, name ) )
				return true;
			from.SendMessage( "The dueling ruleset prevents you from using this move." );
			return false;
		}
